INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0001-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the worst-case time complexity of searching for a target value in a sorted array using Binary Search?', 'int binarySearch(int arr[], int l, int r, int x) {
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0002-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'Which fundamental principle governs the order of insertion and deletion operations in a standard Queue data structure?', NULL, '[{"id": "A", "text": "Last In, First Out (LIFO)"}, {"id": "B", "text": "First In, First Out (FIFO)"}, {"id": "C", "text": "Random Access"}, {"id": "D", "text": "Highest Priority First (HPF)"}]'::jsonb, 'B', 'Easy', 50, 30, 'A queue is an abstract data structure that follows the FIFO (First In, First Out) ordering invariant: elements are enqueued at the rear and dequeued from the front in arrival order.', ARRAY['Queue', 'Abstract Data Types', 'Basics']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0003-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the time complexity of accessing an arbitrary element at index k in a standard singly-linked list of n elements?', NULL, '[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(k)"}, {"id": "C", "text": "O(n)"}, {"id": "D", "text": "O(log n)"}]'::jsonb, 'C', 'Easy', 50, 30, 'Unlike contiguous arrays that offer O(1) random pointer arithmetic access, a singly-linked list requires sequential pointer traversal from the head node, taking O(n) worst-case time.', ARRAY['Linked List', 'Memory Layout', 'Array vs List']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0004-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'Which data structure is inherently used by modern computer architectures and compilers to manage function call frames, local variables, and recursion?', NULL, '[{"id": "A", "text": "Queue"}, {"id": "B", "text": "Call Stack (LIFO)"}, {"id": "C", "text": "Binary Search Tree"}, {"id": "D", "text": "Hash Table"}]'::jsonb, 'B', 'Easy', 50, 30, 'The execution call stack operates strictly on Last In, First Out (LIFO) semantics: invoking a function pushes its activation record onto the stack, and returning pops it off.', ARRAY['Stack', 'Recursion', 'Memory Management']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0005-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In a valid Binary Min-Heap containing n unique numeric keys, where is the minimum element guaranteed to reside?', NULL, '[{"id": "A", "text": "At any arbitrary leaf node"}, {"id": "B", "text": "At the root node (index 0 / 1)"}, {"id": "C", "text": "At the leftmost leaf node"}, {"id": "D", "text": "At index n/2"}]'::jsonb, 'B', 'Easy', 50, 30, 'The min-heap invariant specifies that parent[i] <= child[i] for all nodes. By transitivity, the global minimum key must reside at the root node.', ARRAY['Heap', 'Priority Queue', 'Tree Properties']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0006-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the auxiliary space complexity of representing an undirected graph G = (V, E) using an Adjacency Matrix?', NULL, '[{"id": "A", "text": "O(|V| + |E|)"}, {"id": "B", "text": "O(|V|^2)"}, {"id": "C", "text": "O(|E|^2)"}, {"id": "D", "text": "O(|V| * |E|)"}]'::jsonb, 'B', 'Easy', 50, 30, 'An adjacency matrix allocates a 2D array of size |V| x |V| regardless of the number of edges |E|, yielding a strict space footprint of O(|V|^2).', ARRAY['Graph', 'Adjacency Matrix', 'Space Complexity']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0007-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'Under uniform hashing and a load factor alpha < 1, what is the average-case time complexity of key lookup in a Hash Table?', NULL, '[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(log n)"}, {"id": "C", "text": "O(n)"}, {"id": "D", "text": "O(n^2)"}]'::jsonb, 'A', 'Easy', 50, 30, 'Assuming a uniform hash function that disperses keys evenly across buckets, expected bucket chain length is O(1 + alpha) = O(1).', ARRAY['Hash Table', 'Hashing', 'Average Complexity']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0008-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the worst-case number of comparisons performed by Linear Search on an unsorted array of size n?', NULL, '[{"id": "A", "text": "1"}, {"id": "B", "text": "log2(n)"}, {"id": "C", "text": "n"}, {"id": "D", "text": "n * (n - 1) / 2"}]'::jsonb, 'C', 'Easy', 50, 30, 'When the target item is at the very last index or absent from the array, linear search must examine every single one of the n elements, performing exactly n comparisons.', ARRAY['Linear Search', 'Arrays', 'Basics']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0009-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the maximum height of a strictly balanced Binary Search Tree containing n nodes?', NULL, '[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(log n)"}, {"id": "C", "text": "O(n)"}, {"id": "D", "text": "O(n^2)"}]'::jsonb, 'B', 'Easy', 50, 30, 'Strict self-balancing invariants (such as AVL trees bounding height by ~1.44 log2 n) guarantee that tree height remains O(log n), preventing degenerate linked-list degradation.', ARRAY['BST', 'Trees', 'Height Balance']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0010-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'Which graph traversal strategy uses a FIFO Queue to discover all vertices at distance k before exploring vertices at distance k + 1?', NULL, '[{"id": "A", "text": "Depth-First Search (DFS)"}, {"id": "B", "text": "Breadth-First Search (BFS)"}, {"id": "C", "text": "Topological Sort"}, {"id": "D", "text": "Iterative Deepening DFS"}]'::jsonb, 'B', 'Easy', 50, 30, 'Breadth-First Search (BFS) systematically sweeps outward level-by-level using a FIFO queue, guaranteeing shortest path detection on unweighted graphs.', ARRAY['BFS', 'Graph Traversal', 'Shortest Path']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0011-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What property defines a ''stable'' sorting algorithm?', NULL, '[{"id": "A", "text": "It runs in O(n log n) worst-case time"}, {"id": "B", "text": "It requires zero auxiliary memory (in-place)"}, {"id": "C", "text": "It preserves the relative order of elements with equal keys"}, {"id": "D", "text": "It never performs data swaps"}]'::jsonb, 'C', 'Easy', 50, 30, 'Stability guarantees that if two items share identical key values (e.g. record A and record B where A.key == B.key and A appears before B in input), A will remain before B in the sorted output.', ARRAY['Sorting', 'Stability', 'Algorithms']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0012-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In a max-heap stored in an array with 1-based indexing, where are the children of a node at index i located?', NULL, '[{"id": "A", "text": "i + 1 and i + 2"}, {"id": "B", "text": "2*i and 2*i + 1"}, {"id": "C", "text": "i/2 and i/2 + 1"}, {"id": "D", "text": "2*i - 1 and 2*i"}]'::jsonb, 'B', 'Easy', 50, 30, 'In 1-based binary tree array representations, left_child(i) = 2*i, right_child(i) = 2*i + 1, and parent(i) = floor(i/2).', ARRAY['Heap', 'Array Indexing', 'Binary Trees']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0013-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In an AVL Tree, when a node has a balance factor of +2 and its left child has a balance factor of -1 (Left-Right / LR case), which rotation sequence restores balance?', '      z (+2)
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0014-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'Why does Dijkstra''s algorithm fail to find the correct shortest path on graphs containing negative edge weights?', NULL, '[{"id": "A", "text": "It enters an infinite loop and crashes with stack overflow"}, {"id": "B", "text": "Its greedy choice property assumes that once a vertex is settled, its shortest path cannot be further reduced"}, {"id": "C", "text": "Priority queues cannot store negative numbers"}, {"id": "D", "text": "It only works on undirected bipartite graphs"}]'::jsonb, 'B', 'Medium', 100, 45, 'Dijkstra relies on the invariant that distances in the min-priority queue are monotonically settled. A negative edge can allow a settled node''s distance to decrease retrospectively, invalidating Dijkstra''s greedy finalization.', ARRAY['Dijkstra', 'Greedy', 'Graph Theory', 'Negative Weights']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0015-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In the 0/1 Knapsack problem with N items and weight capacity W, how can the dynamic programming space complexity be reduced from O(N * W) to O(W)?', 'for (int i = 0; i < N; i++) {
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0016-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the tight asymptotic time complexity of Merge Sort on an array of n items?', 'T(n) = 2*T(n/2) + O(n)', '[{"id": "A", "text": "O(n)"}, {"id": "B", "text": "O(n log n)"}, {"id": "C", "text": "O(n^2)"}, {"id": "D", "text": "O(log n)"}]'::jsonb, 'B', 'Medium', 100, 45, 'By Master Theorem Case 2: a=2, b=2, f(n)=O(n). log_b(a) = log2(2) = 1. Since f(n) = Theta(n^1), T(n) = Theta(n log n) in all best, average, and worst cases.', ARRAY['Merge Sort', 'Master Theorem', 'Divide and Conquer']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0017-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In Floyd''s Cycle-Finding Algorithm (Tortoise and Hare) on a linked list, if slow moves 1 step and fast moves 2 steps, how is cycle existence proven?', 'ListNode *slow = head, *fast = head;
