INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0020-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'How does Open Addressing with Quadratic Probing mitigate the primary clustering issue found in Linear Probing?', 'index = (hash(key) + c1 * i + c2 * i^2) % TABLE_SIZE;', '[{"id": "A", "text": "By using a second hash function to rehash colliding keys"}, {"id": "B", "text": "By probing slots at quadratic offsets i^2 rather than consecutive linear steps i, breaking contiguous cluster blocks"}, {"id": "C", "text": "By storing linked lists in each bucket"}, {"id": "D", "text": "By dynamically doubling table size on every collision"}]'::jsonb, 'B', 'Medium', 100, 45, 'Linear probing suffers from primary clustering because occupied blocks grow longer and attract more collisions. Quadratic probing uses quadratic step increments (i^2), skipping over contiguous clusters.', ARRAY['Hashing', 'Collision Resolution', 'Quadratic Probing']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0021-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In Kahn''s Algorithm for Topological Sorting of a Directed Acyclic Graph (DAG), which vertices are initially pushed onto the working queue?', NULL, '[{"id": "A", "text": "Vertices with Out-Degree equal to 0"}, {"id": "B", "text": "Vertices with In-Degree equal to 0"}, {"id": "C", "text": "The vertex with the highest numerical key"}, {"id": "D", "text": "Any arbitrary root vertex"}]'::jsonb, 'B', 'Medium', 100, 45, 'Kahn''s algorithm begins by enqueueing all vertices with an in-degree of 0 (no prerequisite edges). As each vertex is removed from the queue, incoming edge counts of its neighbors are decremented.', ARRAY['Topological Sort', 'DAG', 'Graph Algorithms']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0022-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the recurrence relation for finding the Longest Common Subsequence (LCS) of strings X[0..m-1] and Y[0..n-1] when X[i-1] == Y[j-1]?', NULL, '[{"id": "A", "text": "LCS[i][j] = LCS[i-1][j-1] + 1"}, {"id": "B", "text": "LCS[i][j] = max(LCS[i-1][j], LCS[i][j-1])"}, {"id": "C", "text": "LCS[i][j] = LCS[i-1][j-1] * 2"}, {"id": "D", "text": "LCS[i][j] = min(LCS[i-1][j], LCS[i][j-1]) + 1"}]'::jsonb, 'A', 'Medium', 100, 45, 'When the current characters match (X[i-1] == Y[j-1]), this matching character extends the longest common subsequence of prefixes X[0..i-2] and Y[0..j-2] by exactly 1.', ARRAY['Dynamic Programming', 'LCS', 'Strings']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0023-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the height property of a Red-Black tree that bounds its maximum height to 2 * log2(n + 1)?', NULL, '[{"id": "A", "text": "Every path from root to leaf has exactly the same number of red nodes"}, {"id": "B", "text": "No two red nodes can appear consecutively, and every simple path from root to leaf contains identical black nodes"}, {"id": "C", "text": "The tree cannot have more than 3 levels"}, {"id": "D", "text": "All leaves must be colored red"}]'::jsonb, 'B', 'Medium', 100, 45, 'Since no two red nodes can be adjacent, red nodes must alternate with black nodes. This guarantees the longest path (alternating red-black) is at most twice the shortest path (all black), bounding height to 2 * log2(n + 1).', ARRAY['Red-Black Tree', 'Invariants', 'Trees']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0024-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'When extracting the minimum element from a Binary Min-Heap of size n, what is the time complexity of the heapify-down operation?', NULL, '[{"id": "A", "text": "O(1)"}, {"id": "B", "text": "O(log n)"}, {"id": "C", "text": "O(n)"}, {"id": "D", "text": "O(n log n)"}]'::jsonb, 'B', 'Medium', 100, 45, 'Extracting the min replaces the root with the last leaf element, then percolates down by swapping with the smaller child until heap order is restored. This traverses at most the tree height: O(log n).', ARRAY['Heap', 'Heapify', 'Priority Queue']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0025-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'Which condition allows the Two-Pointer technique to solve the ''Two Sum'' problem in O(n) time and O(1) extra space?', NULL, '[{"id": "A", "text": "The input array must already be sorted in non-decreasing order"}, {"id": "B", "text": "The elements must all be positive integers"}, {"id": "C", "text": "The array must contain an even number of elements"}, {"id": "D", "text": "A hash table must be maintained alongside the pointers"}]'::jsonb, 'A', 'Medium', 100, 45, 'In a sorted array, placing one pointer at start and one at end allows monotonic decisions: if sum < target, increment left pointer; if sum > target, decrement right pointer.', ARRAY['Two Pointers', 'Array', 'Optimization']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0026-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'What is the worst-case time complexity of QuickSelect to find the k-th smallest element when using naive pivot selection?', NULL, '[{"id": "A", "text": "O(n) average, but O(n^2) worst case"}, {"id": "B", "text": "O(log n) always"}, {"id": "C", "text": "O(n log n) strictly"}, {"id": "D", "text": "O(1)"}]'::jsonb, 'A', 'Medium', 100, 45, 'QuickSelect exhibits average O(n) time via T(n) = T(n/2) + O(n). However, if an extreme pivot (e.g. smallest or largest element) is picked repeatedly, it degrades to T(n) = T(n-1) + O(n) = O(n^2).', ARRAY['QuickSelect', 'Pivot', 'Order Statistics']::text[]);
