INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0030-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In Tarjan''s Strongly Connected Components (SCC) algorithm, what does the ''low-link'' value low[u] represent?', NULL, '[{"id": "A", "text": "The out-degree of vertex u"}, {"id": "B", "text": "The smallest discovery time reachable from u through its DFS subtree including at most one back-edge to a node on the stack"}, {"id": "C", "text": "The length of the shortest path from the source node to u"}, {"id": "D", "text": "The number of child nodes under u in the spanning tree"}]'::jsonb, 'B', 'Hard', 200, 60, 'low[u] tracks the earliest visited ancestor reachable from u via tree edges and cross/back-edges still on the active recursion stack. If disc[u] == low[u], u is the root of an SCC.', ARRAY['Tarjan', 'SCC', 'DFS', 'Graph Theory']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0031-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In the Knuth-Morris-Pratt (KMP) string matching algorithm, what does the prefix function value pi[i] store for pattern P[0..m-1]?', NULL, '[{"id": "A", "text": "The hash of substring P[0..i]"}, {"id": "B", "text": "The length of the longest proper prefix of P[0..i] that is also a suffix of P[0..i]"}, {"id": "C", "text": "The index of the first mismatching character in the text"}, {"id": "D", "text": "The number of distinct characters in P[0..i]"}]'::jsonb, 'B', 'Hard', 200, 60, 'The pi table defines the longest proper prefix of P[0..i] that is also a suffix of P[0..i]. On mismatch at P[j], the search pointer falls back to pi[j-1] without re-examining matched text characters, yielding O(n + m) time.', ARRAY['KMP', 'String Matching', 'Prefix Function']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0032-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'For the A* search algorithm to guarantee finding the optimal shortest path on graphs, what mathematical property must its heuristic function h(n) satisfy?', NULL, '[{"id": "A", "text": "h(n) must equal 0 for all nodes"}, {"id": "B", "text": "h(n) must be admissible (never overestimate true cost to goal) and consistent/monotonic (h(n) <= c(n, p) + h(p))"}, {"id": "C", "text": "h(n) must strictly overestimate distance by at least 10%"}, {"id": "D", "text": "h(n) must be calculated using Euclidean distance squared"}]'::jsonb, 'B', 'Hard', 200, 60, 'Admissibility (h(n) <= h*(n)) guarantees optimality in tree search. Consistency (triangle inequality: h(u) <= cost(u, v) + h(v)) guarantees optimality in graph search without re-opening closed nodes.', ARRAY['A* Search', 'Heuristics', 'Graph Search']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000001-0033-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000001', 'In the Matrix Chain Multiplication dynamic programming problem with matrices A1..An of dimensions p0 x p1..pn-1 x pn, what is the state recurrence for m[i, j]?', NULL, '[{"id": "A", "text": "m[i, j] = min_{i <= k < j} (m[i, k] + m[k+1, j] + p_{i-1} * p_k * p_j)"}, {"id": "B", "text": "m[i, j] = m[i, j-1] + p_i * p_j"}, {"id": "C", "text": "m[i, j] = max_{i <= k < j} (m[i, k] * m[k+1, j])"}, {"id": "D", "text": "m[i, j] = m[i+1, j-1] + p_0 * p_n"}]'::jsonb, 'A', 'Hard', 200, 60, 'To multiply chain Ai..Aj, we split at index k. The cost is the scalar multiplications to evaluate Ai..k, plus k+1..j, plus multiplying the two resulting matrices (dimensions p_{i-1} * p_k * p_j).', ARRAY['Matrix Chain Multiplication', 'Dynamic Programming', 'Interval DP']::text[]);
