INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0001-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What fundamental constraint guarantees that every tuple in a relational database table can be uniquely identified and cannot contain NULL values?', NULL, '[{"id": "A", "text": "Foreign Key constraint"}, {"id": "B", "text": "Primary Key constraint"}, {"id": "C", "text": "Check constraint"}, {"id": "D", "text": "Default constraint"}]'::jsonb, 'B', 'Easy', 50, 30, 'A Primary Key enforces entity integrity: each record must have a distinct identifier, and no column in the primary key can be assigned NULL.', ARRAY['Primary Key', 'Relational Model', 'Constraints']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0002-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Which ACID property guarantees that all database modifications within a transaction are completed successfully or entirely rolled back if an error occurs?', NULL, '[{"id": "A", "text": "Atomicity"}, {"id": "B", "text": "Consistency"}, {"id": "C", "text": "Isolation"}, {"id": "D", "text": "Durability"}]'::jsonb, 'A', 'Easy', 50, 30, 'Atomicity (the ''All-or-Nothing'' rule) guarantees that if any statement inside a transaction aborts or fails, the entire transaction is rolled back as if it never ran.', ARRAY['ACID', 'Transactions', 'Atomicity']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0003-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is the primary objective of First Normal Form (1NF) in relational schema design?', NULL, '[{"id": "A", "text": "Removing partial functional dependencies"}, {"id": "B", "text": "Ensuring every column contains only atomic (indivisible) values and eliminating repeating groups"}, {"id": "C", "text": "Removing transitive dependencies"}, {"id": "D", "text": "Enforcing foreign key cascade constraints"}]'::jsonb, 'B', 'Easy', 50, 30, '1NF requires that all column values are atomic (e.g. no comma-separated lists or nested arrays in a single cell) and every row has unique non-repeating entries.', ARRAY['Normalization', '1NF', 'Schema Design']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0004-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Which SQL statement is classified as a Data Definition Language (DDL) command?', NULL, '[{"id": "A", "text": "SELECT"}, {"id": "B", "text": "INSERT"}, {"id": "C", "text": "CREATE TABLE"}, {"id": "D", "text": "UPDATE"}]'::jsonb, 'C', 'Easy', 50, 30, 'DDL commands define and modify the schema structure of the database (CREATE, ALTER, DROP, TRUNCATE), whereas SELECT, INSERT, UPDATE, and DELETE are DML (Data Manipulation Language).', ARRAY['SQL', 'DDL', 'DML']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0005-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is the difference between an INNER JOIN and a LEFT OUTER JOIN in SQL?', NULL, '[{"id": "A", "text": "INNER JOIN returns only matching rows from both tables; LEFT OUTER JOIN returns all rows from the left table plus matched rows from the right table"}, {"id": "B", "text": "INNER JOIN is faster because it deletes non-matching rows from disk"}, {"id": "C", "text": "LEFT OUTER JOIN returns only NULL rows"}, {"id": "D", "text": "There is no functional difference between them"}]'::jsonb, 'A', 'Easy', 50, 30, 'INNER JOIN discards rows from either table that lack a corresponding match on the join predicate. LEFT OUTER JOIN retains every record from the left table, populating right-side columns with NULL if unmatched.', ARRAY['SQL', 'Joins', 'Relational Algebra']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0006-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'How does a Clustered Index affect the physical storage of rows in a database table?', NULL, '[{"id": "A", "text": "It stores index keys in a separate file without altering table order"}, {"id": "B", "text": "It determines the physical sort order of the actual data rows on disk, allowing only one clustered index per table"}, {"id": "C", "text": "It compresses the table into zip format"}, {"id": "D", "text": "It duplicates the entire table into RAM memory"}]'::jsonb, 'B', 'Easy', 50, 30, 'Because physical disk blocks can only be ordered in one sequence, a table can possess exactly one clustered index, whose leaf nodes contain the actual physical row records.', ARRAY['Indexing', 'Clustered Index', 'Storage Engine']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0007-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What does the SQL command TRUNCATE TABLE do compared to DELETE FROM table?', NULL, '[{"id": "A", "text": "TRUNCATE deletes the table schema definition itself"}, {"id": "B", "text": "TRUNCATE deallocates data pages directly as a DDL operation without logging individual row deletions, making it much faster"}, {"id": "C", "text": "TRUNCATE only works on temporary tables"}, {"id": "D", "text": "TRUNCATE allows WHERE clauses for selective deletion"}]'::jsonb, 'B', 'Easy', 50, 30, 'DELETE logs row-by-row deletions and fires triggers. TRUNCATE is a DDL command that deallocates data extents directly, resets auto-increment sequences, and cannot accept a WHERE clause.', ARRAY['SQL', 'Truncate vs Delete', 'Performance']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0008-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'How do standard SQL aggregate functions (such as COUNT(column_name) or AVG(column_name)) treat NULL values?', NULL, '[{"id": "A", "text": "They convert NULLs to 0 and include them in the calculation"}, {"id": "B", "text": "They ignore (skip) NULL values entirely during aggregation (except COUNT(*))"}, {"id": "C", "text": "They return NULL as the aggregate output immediately"}, {"id": "D", "text": "They raise a runtime SQL syntax exception"}]'::jsonb, 'B', 'Easy', 50, 30, 'Aggregate functions on specific columns (COUNT(x), SUM(x), AVG(x)) filter out NULL values. In contrast, COUNT(*) counts total row occurrences regardless of nullability.', ARRAY['SQL', 'Aggregate Functions', 'Null Handling']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0009-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is a Foreign Key in relational database terminology?', NULL, '[{"id": "A", "text": "An encryption key used to access remote databases"}, {"id": "B", "text": "A field or collection of fields in one table that uniquely identifies a row in another table (referential integrity)"}, {"id": "C", "text": "A key that cannot be indexed"}, {"id": "D", "text": "A primary key composed of more than three columns"}]'::jsonb, 'B', 'Easy', 50, 30, 'Foreign keys enforce referential integrity between tables, ensuring that relationships between records remain valid and preventing orphan child rows.', ARRAY['Foreign Key', 'Referential Integrity', 'Relational Schema']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0010-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is a Database View in SQL?', NULL, '[{"id": "A", "text": "A physical backup file saved on secondary storage"}, {"id": "B", "text": "A virtual table defined by an underlying stored SQL query that computes results on demand"}, {"id": "C", "text": "A graphical monitor showing active server connections"}, {"id": "D", "text": "A materialized index cached exclusively in CPU L1 cache"}]'::jsonb, 'B', 'Easy', 50, 30, 'A standard View does not store physical data rows; it represents a saved query definition that the database engine evaluates dynamically when queried.', ARRAY['Views', 'Virtual Tables', 'SQL']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0011-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Which clause in SQL is used to filter groups produced by a GROUP BY clause?', 'SELECT department, COUNT(*) FROM employees GROUP BY department HAVING COUNT(*) > 5;', '[{"id": "A", "text": "WHERE"}, {"id": "B", "text": "HAVING"}, {"id": "C", "text": "ORDER BY"}, {"id": "D", "text": "FILTER"}]'::jsonb, 'B', 'Easy', 50, 30, 'WHERE filters individual rows BEFORE aggregation occurs; HAVING filters aggregated groups AFTER the GROUP BY aggregation is computed.', ARRAY['SQL', 'HAVING', 'GROUP BY']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0012-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is a Candidate Key in relational database theory?', NULL, '[{"id": "A", "text": "Any column that contains numerical values"}, {"id": "B", "text": "A minimal superkey capable of uniquely identifying any record in a relation without redundant attributes"}, {"id": "C", "text": "The key that has the lowest alphabetical character count"}, {"id": "D", "text": "A temporary foreign key used during data migration"}]'::jsonb, 'B', 'Easy', 50, 30, 'A candidate key is a minimal superkey: it possesses uniqueness and minimality (removing any attribute from it destroys its unique identification capability). One candidate key is chosen as the primary key.', ARRAY['Candidate Key', 'Keys', 'Relational Theory']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0013-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'A relational table R(A, B, C, D) has primary key (A, B) and functional dependency B -> C. Which normal form is violated?', NULL, '[{"id": "A", "text": "1NF"}, {"id": "B", "text": "2NF (Second Normal Form)"}, {"id": "C", "text": "3NF"}, {"id": "D", "text": "BCNF"}]'::jsonb, 'B', 'Medium', 100, 45, '2NF mandates that all non-prime attributes must be fully functionally dependent on the entire composite primary key. Since C depends solely on subset attribute B (a partial dependency), the relation violates 2NF.', ARRAY['Normalization', '2NF', 'Functional Dependencies']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0014-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Why do relational databases prefer B+ Trees over standard Binary Search Trees or B-Trees for disk-backed indexing?', NULL, '[{"id": "A", "text": "B+ Trees have fewer nodes than binary trees"}, {"id": "B", "text": "All data pointers are stored exclusively at leaf nodes, leaf nodes are linked sequentially for rapid range scans, and internal nodes store only routing keys for high fan-out"}, {"id": "C", "text": "B+ Trees store records in reverse hash order"}, {"id": "D", "text": "B+ Trees do not require disk I/O operations"}]'::jsonb, 'B', 'Medium', 100, 45, 'High fan-out in B+ Tree internal nodes reduces tree depth to 3-4 levels for millions of records. Furthermore, double-linked leaf nodes enable O(1) page traversals during range queries (BETWEEN x AND y).', ARRAY['B+ Tree', 'Indexing', 'Range Queries', 'Storage']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0015-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Under the ANSI SQL standard, what concurrency anomaly is prevented by the REPEATABLE READ isolation level that can still occur in READ COMMITTED?', NULL, '[{"id": "A", "text": "Dirty Read (reading uncommitted data)"}, {"id": "B", "text": "Non-Repeatable Read (Fuzzy Read)"}, {"id": "C", "text": "Transaction Deadlock"}, {"id": "D", "text": "Hardware disk failure"}]'::jsonb, 'B', 'Medium', 100, 45, 'In READ COMMITTED, reading a row, having another transaction update and commit it, and reading it again returns altered data (Non-Repeatable Read). REPEATABLE READ locks or snapshots read rows, ensuring identical values across queries.', ARRAY['Isolation Levels', 'ACID', 'Concurrency Control']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0016-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'In Two-Phase Locking (2PL), what invariant marks the boundary between the Growing Phase and the Shrinking Phase?', NULL, '[{"id": "A", "text": "Once a transaction releases any single lock, it enters the shrinking phase and is strictly forbidden from acquiring any new locks"}, {"id": "B", "text": "Locks are acquired only after all updates commit"}, {"id": "C", "text": "All read locks are converted to shared locks"}, {"id": "D", "text": "The transaction must restart from the beginning"}]'::jsonb, 'A', 'Medium', 100, 45, '2PL guarantees serializability by segregating execution: in the Growing Phase, locks may be obtained but not released; once the lock point is reached and ANY lock is released, no new locks can ever be acquired.', ARRAY['2PL', 'Two-Phase Locking', 'Serializability']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0017-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is the Leftmost Prefix Rule when executing queries against a composite index (col_a, col_b, col_c)?', 'CREATE INDEX idx_abc ON users (col_a, col_b, col_c);', '[{"id": "A", "text": "The index can only be used if all three columns are in the WHERE clause"}, {"id": "B", "text": "The query optimizer can utilize the index for conditions on (col_a), (col_a, col_b), or (col_a, col_b, col_c), but NOT on (col_b) or (col_c) alone"}, {"id": "C", "text": "The columns must be ordered alphabetically in the SELECT list"}, {"id": "D", "text": "The index is sorted from right to left"}]'::jsonb, 'B', 'Medium', 100, 45, 'Composite B-tree indexes sort keys lexicographically starting from the leftmost column. Without a condition constraining col_a, the B-tree cannot be navigated hierarchically for col_b alone.', ARRAY['Composite Index', 'Query Optimization', 'B+ Tree']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0018-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'How does Write-Ahead Logging (WAL) uphold durability and crash recovery in database engines?', NULL, '[{"id": "A", "text": "It writes log records to non-volatile disk BEFORE corresponding dirty data pages are flushed from the buffer pool to disk"}, {"id": "B", "text": "It mirrors the entire database to a cloud replica before executing queries"}, {"id": "C", "text": "It delays disk writes until system shutdown"}, {"id": "D", "text": "It eliminates the need for RAM caching"}]'::jsonb, 'A', 'Medium', 100, 45, 'WAL guarantees that changes are sequentially appended to a persistent redo log before the data page is written. On crash, the engine replays REDO logs to reconstruct committed states and applies UNDO logs for uncommitted ones.', ARRAY['WAL', 'Crash Recovery', 'Durability', 'Storage']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0019-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'A relation is in Third Normal Form (3NF) if for every non-trivial functional dependency X -> Y, which condition holds?', NULL, '[{"id": "A", "text": "X must be an index and Y must be an integer"}, {"id": "B", "text": "Either X is a superkey, or Y is a prime attribute (part of a candidate key)"}, {"id": "C", "text": "Y must be a foreign key referencing an external table"}, {"id": "D", "text": "X and Y must contain identical numbers of columns"}]'::jsonb, 'B', 'Medium', 100, 45, '3NF eliminates transitive dependencies. In BCNF, X must strictly be a superkey; 3NF allows the relaxation that Y may be a prime attribute (part of some candidate key), which preserves dependencies.', ARRAY['3NF', 'Normalization', 'Functional Dependencies']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0020-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'In deadlock prevention, what distinguishes the Wait-Die scheme from the Wound-Wait scheme based on transaction timestamps?', NULL, '[{"id": "A", "text": "Wait-Die is non-preemptive (an older transaction waits for a younger one, but a younger transaction dies); Wound-Wait is preemptive (an older transaction wounds/aborts a younger one)"}, {"id": "B", "text": "Wait-Die only works in distributed databases"}, {"id": "C", "text": "Wound-Wait allows transactions to wait forever without timeouts"}, {"id": "D", "text": "Both schemes immediately abort older transactions on conflict"}]'::jsonb, 'A', 'Medium', 100, 45, 'In Wait-Die, if Ti (older) requests a lock held by Tj (younger), Ti is allowed to wait; if Ti is younger, it dies. In Wound-Wait, if Ti is older, it preempts (''wounds'') Tj, forcing Tj to abort and rollback.', ARRAY['Deadlock', 'Concurrency', 'Timestamps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0021-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What performance problem occurs when executing a Correlated Subquery over a large table compared to an equivalent JOIN?', 'SELECT e1.name, e1.salary FROM employees e1 
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0022-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is the function of the ARIES recovery algorithm''s Analysis pass during crash recovery?', NULL, '[{"id": "A", "text": "It rolls back all transactions immediately"}, {"id": "B", "text": "It scans the log forward from the most recent checkpoint to reconstruct the active transaction table and dirty page table at the time of crash"}, {"id": "C", "text": "It checks disk bad sectors"}, {"id": "D", "text": "It writes new checkpoint records to disk"}]'::jsonb, 'B', 'Medium', 100, 45, 'ARIES operates in three passes: 1) Analysis pass reconstructs the state of the system at crash time; 2) REDO pass repeats history to restore the database to crash moment; 3) UNDO pass rolls back active transactions.', ARRAY['ARIES', 'Recovery', 'Transactions']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0023-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Why does Boyce-Codd Normal Form (BCNF) strictly disallow functional dependencies where X -> Y if X is not a superkey?', NULL, '[{"id": "A", "text": "Because it causes table creation to fail"}, {"id": "B", "text": "To eliminate all redundancy resulting from functional dependencies, even when Y is a prime attribute"}, {"id": "C", "text": "Because BCNF tables can only have one column"}, {"id": "D", "text": "To guarantee that foreign keys are disabled"}]'::jsonb, 'B', 'Medium', 100, 45, 'In 3NF, X -> Y is allowed if Y is prime. BCNF removes this exception: every non-trivial determinant X MUST be a superkey, completely eradicating update and deletion anomalies.', ARRAY['BCNF', 'Normalization', 'Relational Theory']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0024-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What is the difference between Optimistic Concurrency Control (OCC) and Pessimistic Concurrency Control (PCC)?', NULL, '[{"id": "A", "text": "OCC assumes conflicts are rare, executing transactions without locking and validating conflicts at commit time; PCC locks data up-front to prevent concurrent conflicts"}, {"id": "B", "text": "OCC does not support ACID guarantees"}, {"id": "C", "text": "PCC is only used in NoSQL databases"}, {"id": "D", "text": "OCC locks the entire table during read operations"}]'::jsonb, 'A', 'Medium', 100, 45, 'PCC uses shared and exclusive locks (2PL), preventing conflicts by blocking other transactions. OCC proceeds through Read, Validate, and Write phases without locks, aborting and retrying only if conflict is detected.', ARRAY['Concurrency', 'OCC vs PCC', 'Transactions']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0025-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'In a SQL database using Multi-Version Concurrency Control (MVCC), how do read queries achieve lock-free non-blocking operation?', NULL, '[{"id": "A", "text": "By executing against an in-memory replica exclusively"}, {"id": "B", "text": "By reading older row versions (snapshots) visible to the transaction timestamp without waiting for write locks to release"}, {"id": "C", "text": "By bypassing foreign keys and transaction logs"}, {"id": "D", "text": "By converting all write queries to background jobs"}]'::jsonb, 'B', 'Medium', 100, 45, 'Under MVCC (Postgres, InnoDB), writers create new row versions (xmin/xmax or rollback segments) rather than overwriting in-place. Readers look at a consistent snapshot, meaning ''readers never block writers, and writers never block readers''.', ARRAY['MVCC', 'Snapshot Isolation', 'Lock-Free']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0026-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What happens when an index has low selectivity (e.g. a column with only 2 distinct values across 1,000,000 rows)?', 'CREATE INDEX idx_gender ON users (gender);', '[{"id": "A", "text": "The index accelerates queries by 50%"}, {"id": "B", "text": "The query optimizer will likely reject the index in favor of a sequential Full Table Scan, because random disk I/O from index lookups costs more than sequential reading"}, {"id": "C", "text": "The database returns an error on index creation"}, {"id": "D", "text": "The index automatically converts into a hash table"}]'::jsonb, 'B', 'Medium', 100, 45, 'Selectivity is the ratio of distinct values to total rows. If an index matches 50% of the table, random page fetches via the index are far slower than a sequential scan reading multiple blocks at once.', ARRAY['Index Selectivity', 'Query Optimizer', 'Performance']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0027-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Under Snapshot Isolation in MVCC databases, what is the Write Skew anomaly that violates strict serializability?', '-- Invariant: balance_a + balance_b >= 0
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0028-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'How does a B+ Tree maintain structural balance and invariant compliance when an insertion causes a leaf node to exceed maximum capacity M?', NULL, '[{"id": "A", "text": "The node splits into two nodes of ceil(M/2) keys each, and a COPY of the middle key is pushed up to the parent node while remaining in the leaf"}, {"id": "B", "text": "The middle key is deleted from the tree entirely"}, {"id": "C", "text": "The entire tree is recreated as an AVL tree"}, {"id": "D", "text": "The node is replaced by a hash bucket linked list"}]'::jsonb, 'A', 'Hard', 200, 60, 'In B+ trees, all data records must remain in the leaf level. Therefore, when a leaf splits, the split key is COPIED to the parent as a routing separator while also staying in the right leaf child. In internal node splits, the middle key is MOVED up.', ARRAY['B+ Tree', 'Node Splitting', 'Storage Engine']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0029-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'In Strict Two-Phase Locking (Strict 2PL), why must all exclusive (X) locks be held until the very end of the transaction (Commit or Abort)?', NULL, '[{"id": "A", "text": "To prevent cascading aborts and guarantee recoverable schedules"}, {"id": "B", "text": "To prevent other transactions from reading the database schema"}, {"id": "C", "text": "To reduce lock memory consumption in the lock manager"}, {"id": "D", "text": "Because SQLite requires it"}]'::jsonb, 'A', 'Hard', 200, 60, 'If T1 updates an item, releases its exclusive lock early, and then aborts, any transaction T2 that read T1''s modified value must also abort (cascading abort). Strict 2PL holds exclusive locks until commit, guaranteeing strict schedules.', ARRAY['Strict 2PL', 'Cascading Aborts', 'Concurrency Control']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0030-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'Why do Log-Structured Merge-trees (LSM Trees, like RocksDB/Cassandra) provide substantially higher write throughput than B+ Trees on NVMe/SSD storage?', NULL, '[{"id": "A", "text": "LSM trees bypass secondary storage and write solely to network sockets"}, {"id": "B", "text": "LSM trees convert random in-place page writes into sequential appends in an in-memory MemTable and append-only commit log, deferring sorted disk writes to background compaction"}, {"id": "C", "text": "LSM trees eliminate read operations entirely"}, {"id": "D", "text": "LSM trees do not support indices"}]'::jsonb, 'B', 'Hard', 200, 60, 'B+ trees require in-place random writes to disk pages (high write amplification and random I/O). LSM trees write sequentially to an append log and memory buffer (MemTable), later flushing immutable SSTables sequentially to disk.', ARRAY['LSM Tree', 'Storage Engines', 'Write Amplification', 'B+ Tree']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0031-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'In relational query processing, when is a Hash Join preferred by the cost-based query optimizer over a Sort-Merge Join?', NULL, '[{"id": "A", "text": "When the join condition involves inequalities (e.g. t1.val > t2.val)"}, {"id": "B", "text": "When evaluating an equi-join on large unsorted tables where the smaller table fits entirely in the working memory (hash table buffer)"}, {"id": "C", "text": "When both tables are already indexed and sorted on the join key"}, {"id": "D", "text": "Only when the tables contain fewer than 10 rows"}]'::jsonb, 'B', 'Hard', 200, 60, 'Hash Join builds an in-memory hash table on the smaller relation, then probes it in a single pass of the larger relation (O(M + N)). Sort-Merge Join requires both inputs to be sorted (O(M log M + N log N)), making it preferred only when inputs are already sorted.', ARRAY['Hash Join', 'Sort-Merge Join', 'Query Optimizer']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0032-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'In distributed database systems using Two-Phase Commit (2PC), what critical vulnerability exists if the Coordinator node crashes after participants vote ''YES''?', NULL, '[{"id": "A", "text": "The entire database is corrupted and must be restored from tape backup"}, {"id": "B", "text": "Participants become blocked (in an uncertain state) holding locks indefinitely, unable to unilaterally commit or abort until the coordinator recovers"}, {"id": "C", "text": "All participants automatically abort within 1 millisecond"}, {"id": "D", "text": "The network switches to UDP mode"}]'::jsonb, 'B', 'Hard', 200, 60, '2PC is a blocking protocol. If participants have voted ''YES'' in Phase 1 and the coordinator dies before broadcasting COMMIT/ABORT in Phase 2, participants cannot determine the outcome without risking inconsistency, causing lock blocking.', ARRAY['2PC', 'Distributed Transactions', 'Two-Phase Commit']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000002-0033-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000002', 'What test determines whether a schema decomposition of relation R into (R1, R2) with functional dependencies F is a Lossless-Join Decomposition?', NULL, '[{"id": "A", "text": "R1 union R2 must contain all foreign keys"}, {"id": "B", "text": "The common attributes (R1 intersect R2) must form a superkey of either R1 or R2 (i.e. (R1 intersect R2) -> R1 or (R1 intersect R2) -> R2 in F+)"}, {"id": "C", "text": "R1 and R2 must have an equal number of columns"}, {"id": "D", "text": "The Cartesian product of R1 and R2 must equal R"}]'::jsonb, 'B', 'Hard', 200, 60, 'A decomposition is lossless if and only if the natural join of decomposed relations reproduces the original relation without spurious tuples. This holds if and only if R1 intersect R2 is a superkey of at least one of the decomposed relations.', ARRAY['Lossless Join', 'Normalization', 'Relational Theory']::text[]);
