INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0001-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the correct top-to-bottom sequence of the 7 layers in the ISO-OSI Reference Model?', NULL, '[{"id": "A", "text": "Application, Presentation, Session, Transport, Network, Data Link, Physical"}, {"id": "B", "text": "Physical, Network, Transport, Data Link, Session, Presentation, Application"}, {"id": "C", "text": "Application, Transport, Network, Link, Physical, Session, Presentation"}, {"id": "D", "text": "Data Link, Network, Transport, Session, Presentation, Application, Physical"}]'::jsonb, 'A', 'Easy', 50, 30, 'From Layer 7 down to Layer 1, the OSI model consists of: Application (L7), Presentation (L6), Session (L5), Transport (L4), Network (L3), Data Link (L2), and Physical (L1).', ARRAY['OSI Model', 'Networking Basics', 'Layering']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0002-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the primary operational distinction between Transmission Control Protocol (TCP) and User Datagram Protocol (UDP)?', NULL, '[{"id": "A", "text": "TCP is connectionless and unreliable; UDP is connection-oriented and reliable"}, {"id": "B", "text": "TCP provides connection-oriented, reliable, in-order byte stream delivery with flow and congestion control; UDP provides connectionless, lightweight, unreliable datagram transmission"}, {"id": "C", "text": "TCP only works on fiber optic cables; UDP only works over Wi-Fi"}, {"id": "D", "text": "UDP encrypts data by default; TCP transmits in plain text"}]'::jsonb, 'B', 'Easy', 50, 30, 'TCP establishes a 3-way handshake, retransmits lost segments, and enforces in-order delivery via sequence numbers and ACKs. UDP has zero handshake overhead, no retransmissions, and minimal 8-byte headers.', ARRAY['TCP vs UDP', 'Transport Layer', 'Protocols']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0003-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How many total bits make up a standard IPv4 address, and how is it typically represented in human-readable form?', NULL, '[{"id": "A", "text": "16 bits, written in octal"}, {"id": "B", "text": "32 bits, written as four decimal octets separated by dots (e.g. 192.168.1.1)"}, {"id": "C", "text": "64 bits, written in base64"}, {"id": "D", "text": "128 bits, written as eight colon-separated hexadecimal blocks"}]'::jsonb, 'B', 'Easy', 50, 30, 'IPv4 uses a 32-bit address space (yielding ~4.3 billion possible addresses), formatted as four 8-bit octets (0-255) separated by periods. IPv6 uses 128 bits.', ARRAY['IPv4', 'IP Addressing', 'Network Layer']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0004-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the functional purpose of the Domain Name System (DNS) in computer networking?', NULL, '[{"id": "A", "text": "To compress HTML and CSS files on web servers"}, {"id": "B", "text": "To translate human-readable domain names (e.g. classroyale.com) into numerical IP addresses (e.g. 104.21.52.1) required for routing"}, {"id": "C", "text": "To encrypt Wi-Fi passwords"}, {"id": "D", "text": "To allocate MAC addresses to network interfaces"}]'::jsonb, 'B', 'Easy', 50, 30, 'DNS is the Internet''s hierarchical distributed lookup directory, mapping human-friendly alphanumeric domain names to machine-routable IPv4/IPv6 addresses via A and AAAA resource records.', ARRAY['DNS', 'Application Layer', 'Name Resolution']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0005-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What type of address operates at Layer 2 (Data Link Layer) to uniquely identify physical network interface controllers (NICs) on a local network segment?', NULL, '[{"id": "A", "text": "IP Address"}, {"id": "B", "text": "Media Access Control (MAC) Address (48-bit)"}, {"id": "C", "text": "Port Number"}, {"id": "D", "text": "Socket Descriptor"}]'::jsonb, 'B', 'Easy', 50, 30, 'A MAC address is a 48-bit globally unique hardware identifier burned into the NIC (formatted as 6 pairs of hexadecimal digits like 00:1A:2B:3C:4D:5E). Layer 2 Ethernet switches switch frames based on MAC addresses.', ARRAY['MAC Address', 'Data Link Layer', 'Ethernet']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0006-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the valid port range for TCP and UDP communication endpoints?', NULL, '[{"id": "A", "text": "0 to 255"}, {"id": "B", "text": "0 to 1,024"}, {"id": "C", "text": "0 to 65,535 (16 bits)"}, {"id": "D", "text": "0 to 4,294,967,295"}]'::jsonb, 'C', 'Easy', 50, 30, 'Transport layer headers allocate 16 bits for Source Port and 16 bits for Destination Port, yielding 2^16 = 65,536 total possible port numbers (0 to 65535). 0-1023 are Well-Known ports.', ARRAY['Port Numbers', 'Transport Layer', 'TCP/UDP']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0007-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What does the HTTP 404 response status code signify?', NULL, '[{"id": "A", "text": "Request Succeeded (OK)"}, {"id": "B", "text": "Unauthorized authentication credentials"}, {"id": "C", "text": "Not Found (The server cannot locate the requested resource URI)"}, {"id": "D", "text": "Internal Server Error"}]'::jsonb, 'C', 'Easy', 50, 30, 'HTTP status codes in the 4xx range indicate client-side errors. Specifically, 404 Not Found indicates that the origin server did not find a current representation for the target resource.', ARRAY['HTTP Status Codes', 'Web Protocols', 'Application Layer']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0008-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the function of the Default Gateway in a local network host''s IP routing configuration?', NULL, '[{"id": "A", "text": "To filter email spam"}, {"id": "B", "text": "The router interface address to which a host forwards IP packets destined for external IP subnets outside its local subnet mask"}, {"id": "C", "text": "To assign hostnames to printers"}, {"id": "D", "text": "To provide power over Ethernet"}]'::jsonb, 'B', 'Easy', 50, 30, 'When a host determines that the destination IP address does not reside within its local broadcast domain (via bitwise AND with its subnet mask), it routes the packet to the Default Gateway''s MAC address.', ARRAY['Default Gateway', 'Routing', 'IP Configuration']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0009-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How does an Ethernet Switch (Layer 2) improve network performance compared to a legacy Ethernet Hub (Layer 1)?', NULL, '[{"id": "A", "text": "A hub creates dedicated point-to-point connections; a switch broadcasts all traffic"}, {"id": "B", "text": "A switch maintains a MAC address table to forward frames exclusively to the specific destination port, providing microsegmentation and eliminating collisions; a hub blindly broadcasts all incoming bits to every port"}, {"id": "C", "text": "A hub operates at gigabit speeds while a switch operates at 10 Mbps"}, {"id": "D", "text": "A switch converts Ethernet into radio signals"}]'::jsonb, 'B', 'Easy', 50, 30, 'Hubs repeat physical signals to all connected cables in a single shared collision domain. Switches inspect destination MAC headers, forwarding traffic only to the designated port and enabling full-duplex simultaneous communications.', ARRAY['Switch vs Hub', 'Collision Domain', 'Data Link Layer']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0010-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'Which network utility uses ICMP (Internet Control Message Protocol) Echo Request and Echo Reply messages to test host reachability and round-trip time?', 'PING 8.8.8.8 (8.8.8.8): 56 data bytes
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0011-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the broadcast IPv4 address for a local network subnet configured with 192.168.1.0/24?', NULL, '[{"id": "A", "text": "192.168.1.0"}, {"id": "B", "text": "192.168.1.1"}, {"id": "C", "text": "192.168.1.254"}, {"id": "D", "text": "192.168.1.255"}]'::jsonb, 'D', 'Easy', 50, 30, 'In a /24 subnet (mask 255.255.255.0), the first 24 bits designate the network ID (192.168.1.0) and the remaining 8 bits designate host addresses. Setting all host bits to 1 (255) defines the subnet broadcast address.', ARRAY['Subnetting', 'Broadcast Address', 'IPv4']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0012-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the difference between Full-Duplex and Half-Duplex transmission modes?', NULL, '[{"id": "A", "text": "Full-duplex allows simultaneous bidirectional communication on the medium; half-duplex allows communication in both directions, but only one direction at a time"}, {"id": "B", "text": "Half-duplex uses two cables; full-duplex uses half a cable"}, {"id": "C", "text": "Full-duplex is limited to 100 meters"}, {"id": "D", "text": "There is no functional difference"}]'::jsonb, 'A', 'Easy', 50, 30, 'Walkie-talkies are half-duplex (one speaker at a time). Telephone conversations and modern switched Ethernet are full-duplex (both parties can transmit and receive data frames concurrently over separate wire pairs).', ARRAY['Full-Duplex', 'Half-Duplex', 'Physical Layer']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0013-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What sequence of packets constitutes the TCP Three-Way Handshake used to establish a reliable connection between Client and Server?', 'Client                     Server
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0014-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'In the TCP sliding window flow control protocol, what does the ''Receive Window'' (rwnd) field advertised by the receiver indicate?', NULL, '[{"id": "A", "text": "The maximum bandwidth in megabits per second"}, {"id": "B", "text": "The amount of buffer space currently free in the receiver''s socket buffer, informing the sender how many unacknowledged bytes it may transmit without overflowing the receiver"}, {"id": "C", "text": "The physical monitor display width"}, {"id": "D", "text": "The total number of packets dropped by routers along the path"}]'::jsonb, 'B', 'Medium', 100, 45, 'Flow control protects the receiver from being overwhelmed by a fast sender. The receiver reports its available receive buffer size (rwnd) in every ACK header; the sender limits in-flight bytes to min(cwnd, rwnd).', ARRAY['Flow Control', 'Sliding Window', 'TCP', 'rwnd']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0015-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'In TCP Congestion Control (Tahoe / Reno), how does the Congestion Window (cwnd) grow during the ''Slow Start'' phase upon receiving positive ACKs?', NULL, '[{"id": "A", "text": "Linearly: cwnd increases by 1 MSS per round trip time (RTT)"}, {"id": "B", "text": "Exponentially: cwnd doubles every RTT (increasing by 1 MSS for every received valid ACK) until reaching the slow-start threshold (ssthresh)"}, {"id": "C", "text": "It remains strictly constant"}, {"id": "D", "text": "It decreases by half on every ACK"}]'::jsonb, 'B', 'Medium', 100, 45, 'Despite its name, Slow Start probes available bandwidth with exponential growth: starting at an initial window of 1-10 MSS, each ACK increments cwnd by 1 MSS, effectively doubling the window every round trip time.', ARRAY['Congestion Control', 'Slow Start', 'TCP', 'cwnd']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0016-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What protocol resolves a known Layer 3 IP address to its corresponding Layer 2 MAC address on an Ethernet local area network?', NULL, '[{"id": "A", "text": "Address Resolution Protocol (ARP)"}, {"id": "B", "text": "Dynamic Host Configuration Protocol (DHCP)"}, {"id": "C", "text": "Border Gateway Protocol (BGP)"}, {"id": "D", "text": "Simple Network Management Protocol (SNMP)"}]'::jsonb, 'A', 'Medium', 100, 45, 'ARP broadcasts an ''ARP Request'' packet to FF:FF:FF:FF:FF:FF asking ''Who has IP X.X.X.X? Tell Y.Y.Y.Y''. The host with that IP unicasts an ''ARP Reply'' containing its hardware MAC address.', ARRAY['ARP', 'Data Link Layer', 'Address Resolution']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0017-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is the primary operational difference between Distance-Vector routing (RIP) and Link-State routing (OSPF)?', NULL, '[{"id": "A", "text": "Distance-vector routers share their full routing table with immediate neighbors using Bellman-Ford; link-state routers broadcast connectivity state to all network routers, running Dijkstra''s SPF algorithm on the complete global topology graph"}, {"id": "B", "text": "Distance-vector only works with optical fiber"}, {"id": "C", "text": "OSPF cannot detect link failures"}, {"id": "D", "text": "RIP guarantees zero convergence time in all networks"}]'::jsonb, 'A', 'Medium', 100, 45, 'Distance-Vector is ''routing by rumor'' (sharing distance vectors to immediate peers). Link-State (OSPF/IS-IS) floods Link State Advertisements (LSAs) so every node builds an identical topology map and computes shortest paths via Dijkstra.', ARRAY['OSPF', 'RIP', 'Routing Protocols', 'Link-State vs Distance-Vector']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0018-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How does Network Address Translation (NAT) with Port Address Translation (NAPT / PAT) allow hundreds of internal private hosts to share a single public IPv4 address?', NULL, '[{"id": "A", "text": "By rewriting source IP addresses to the public IP and mapping each private host''s connection to a unique source TCP/UDP port number in an in-memory translation table"}, {"id": "B", "text": "By compressing IP packets using gzip"}, {"id": "C", "text": "By converting all traffic to DNS text records"}, {"id": "D", "text": "By disabling the TCP handshake"}]'::jsonb, 'A', 'Medium', 100, 45, 'PAT multiplexes traffic across a single external IPv4 address by assigning distinct ephemeral port numbers (e.g. 192.168.1.5:4500 -> 203.0.113.1:50001), allowing routers to demultiplex returning response packets.', ARRAY['NAT', 'PAT', 'Network Layer', 'IPv4']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0019-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'Why does the TCP protocol enter the TIME_WAIT state for 2 * Maximum Segment Lifetime (2*MSL) upon closing a connection?', NULL, '[{"id": "A", "text": "To allow time for the final ACK to reach the remote peer (and retransmit if lost), and to ensure delayed stale duplicate segments from the old connection die out in the network before port reuse"}, {"id": "B", "text": "To wait for the operating system to shut down"}, {"id": "C", "text": "To charge the client for bandwidth usage"}, {"id": "D", "text": "Because RFC 793 requires a 10-minute pause"}]'::jsonb, 'A', 'Medium', 100, 45, 'If the active closer''s final ACK is lost, the peer retransmits FIN; the closer in TIME_WAIT can resend the ACK. Furthermore, waiting 2*MSL (typically 60-120 seconds) drains any phantom segments wandering through old internet routes.', ARRAY['TIME_WAIT', 'TCP Teardown', 'MSL']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0020-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How does TLS 1.3 achieve a 1-RTT handshake compared to the legacy 2-RTT handshake in TLS 1.2?', NULL, '[{"id": "A", "text": "The client generates and sends speculative Diffie-Hellman key shares directly inside its initial ClientHello message, allowing the server to derive symmetric session keys and finish the handshake in one round trip"}, {"id": "B", "text": "TLS 1.3 disables public key cryptography entirely"}, {"id": "C", "text": "TLS 1.3 transmits passwords in plain text"}, {"id": "D", "text": "TLS 1.3 operates at Layer 2 instead of Layer 4"}]'::jsonb, 'A', 'Medium', 100, 45, 'TLS 1.2 required negotiating cipher suites in Round 1 before exchanging key parameters in Round 2. TLS 1.3 pruned outdated algorithms and has the client guess common key exchange groups (X25519) up-front, completing encryption setup in 1 RTT.', ARRAY['TLS 1.3', 'Cryptography', 'Handshake Latency', 'HTTPS']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0021-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What problem does the Border Gateway Protocol (BGP) solve that interior routing protocols (like OSPF) cannot handle?', NULL, '[{"id": "A", "text": "It routes traffic across independent Autonomous Systems (AS) across the global Internet using policy-based path-vector routing rather than simple shortest metric calculation"}, {"id": "B", "text": "It speeds up home Wi-Fi speeds"}, {"id": "C", "text": "It assigns IP addresses to smartphones automatically"}, {"id": "D", "text": "It replaces Ethernet cables with radio frequencies"}]'::jsonb, 'A', 'Medium', 100, 45, 'BGP is the exterior gateway protocol glue of the global Internet. Because ISPs have business agreements, peering policies, and country-level transit rules, BGP routes based on administrative policies, AS-Paths, and commercial peering contracts.', ARRAY['BGP', 'Autonomous Systems', 'Internet Routing']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0022-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What is Head-of-Line (HoL) Blocking at the application layer in HTTP/1.1 with pipelining, and how does HTTP/2 solve it?', NULL, '[{"id": "A", "text": "In HTTP/1.1, responses on a TCP connection must be returned in the exact order requested; HTTP/2 splits streams into independent interleaved frames multiplexed across a single TCP socket"}, {"id": "B", "text": "HTTP/1.1 blocks if images are larger than 1MB"}, {"id": "C", "text": "HTTP/2 requires fiber optic cabling to function"}, {"id": "D", "text": "HTTP/1.1 cannot transmit JSON data"}]'::jsonb, 'A', 'Medium', 100, 45, 'In HTTP/1.1 pipelining, if request 1 takes 5 seconds to compute, responses for requests 2 and 3 are stalled behind it on the TCP pipe. HTTP/2 introduces binary framing and stream IDs, interleaving chunked frames without strict sequential blocking.', ARRAY['HTTP/2', 'HTTP/1.1', 'Multiplexing', 'HoL Blocking']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0023-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What are the four sequential message exchanges in the Dynamic Host Configuration Protocol (DHCP) DORA process?', 'Client                       DHCP Server
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0024-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'What occurs when an IPv4 packet exceeds the Maximum Transmission Unit (MTU) of an intermediate link and has its Don''t Fragment (DF) bit set to 1?', NULL, '[{"id": "A", "text": "The router fragments the packet anyway"}, {"id": "B", "text": "The router drops the packet and transmits an ICMP Type 3 Code 4 (''Fragmentation Needed and DF set'') message back to the source host for Path MTU Discovery (PMTUD)"}, {"id": "C", "text": "The packet is rerouted to a satellite link"}, {"id": "D", "text": "The router increases its MTU dynamically"}]'::jsonb, 'B', 'Medium', 100, 45, 'The DF bit prohibits fragmentation. When too large for the link, the router must discard the packet and alert the sender via ICMP, including the Next-Hop MTU value so the sender can adjust its packet size (Path MTU Discovery).', ARRAY['MTU', 'Fragmentation', 'PMTUD', 'ICMP']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0025-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'In IEEE 802.1Q Virtual Local Area Networks (VLANs), where is the 4-byte VLAN tag inserted inside an Ethernet frame?', '| Preamble | Dest MAC | Src MAC | [802.1Q Tag: 4 Bytes] | EtherType | Payload | FCS |', '[{"id": "A", "text": "Between the Source MAC address and the EtherType/Length field"}, {"id": "B", "text": "At the very end of the frame after the FCS checksum"}, {"id": "C", "text": "Inside the IP packet header"}, {"id": "D", "text": "Before the Preamble sequence"}]'::jsonb, 'A', 'Medium', 100, 45, '802.1Q inserts a 4-byte header containing a 12-bit VLAN Identifier (VID, supporting 4,096 VLANs) and 3-bit Priority Code Point (PCP) directly between the Source MAC address and the EtherType field on trunk links.', ARRAY['VLAN', '802.1Q', 'Ethernet Frame', 'Trunking']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0026-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How does ARP Spoofing (ARP Poisoning) compromise a local switched network segment?', NULL, '[{"id": "A", "text": "By flooding the physical cable with high voltage"}, {"id": "B", "text": "By sending unsolicited (gratuitous) fake ARP replies to poison victim hosts'' ARP caches, binding the gateway''s IP address to the attacker''s MAC address for Man-in-the-Middle (MitM) interception"}, {"id": "C", "text": "By disabling the DNS server on the gateway"}, {"id": "D", "text": "By changing the WiFi SSID password"}]'::jsonb, 'B', 'Medium', 100, 45, 'Because traditional ARP is stateless and unauthenticated, devices unconditionally update their ARP cache upon receiving ARP replies. An attacker broadcasts fake replies claiming to own the gateway IP, routing all victim traffic through the attacker.', ARRAY['ARP Spoofing', 'Network Security', 'MitM']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0027-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How does Google''s TCP BBR (Bottleneck Bandwidth and RTT) congestion control algorithm fundamentally differ from loss-based algorithms like TCP Cubic or Reno?', NULL, '[{"id": "A", "text": "BBR models the physical network by measuring maximum delivery rate (BtlBw) and minimum round-trip time (RTprop), operating at Kleinrock''s optimal operating point rather than interpreting packet loss as congestion"}, {"id": "B", "text": "BBR intentionally drops 10% of packets to test router reliability"}, {"id": "C", "text": "BBR uses UDP transport exclusively"}, {"id": "D", "text": "BBR requires specialized hardware inside every intermediate internet router"}]'::jsonb, 'A', 'Hard', 200, 60, 'Loss-based algorithms (Cubic/Reno) pump data until buffers fill and packets drop, causing bufferbloat and latency spikes. BBR measures bandwidth-delay product (BDP = BtlBw * RTprop), keeping inflight data capped at pipe capacity without queuing delay.', ARRAY['TCP BBR', 'TCP Cubic', 'Congestion Control', 'Bufferbloat']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0028-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How does the QUIC protocol (HTTP/3) resolve the Transport-Layer Head-of-Line blocking inherent to HTTP/2 over TCP?', NULL, '[{"id": "A", "text": "By running over UDP and implementing independent per-stream retransmission queues: a dropped packet on Stream A pauses only Stream A, while Streams B and C continue uninterrupted"}, {"id": "B", "text": "By disabling retransmissions entirely like live audio streaming"}, {"id": "C", "text": "By allocating a dedicated physical fiber optic core for every HTTP connection"}, {"id": "D", "text": "By requiring clients to open 100 simultaneous TCP connections"}]'::jsonb, 'A', 'Hard', 200, 60, 'In HTTP/2 over TCP, if a single TCP packet is dropped, TCP blocks ALL byte stream delivery until the packet is retransmitted (transport HoL blocking). QUIC operates over UDP with independent cryptographic streams; packet loss in one stream never blocks other streams.', ARRAY['QUIC', 'HTTP/3', 'Transport Layer', 'UDP']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0029-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How do SYN Cookies defend against TCP SYN Flood Denial-of-Service attacks without consuming server memory state?', NULL, '[{"id": "A", "text": "The server does not allocate a SYN-Queue (half-open connection) buffer; instead, it encodes a cryptographic hash of (src IP, src port, dst IP, dst port, timestamp, secret) into the initial sequence number of the SYN-ACK"}, {"id": "B", "text": "By blocking all incoming TCP connections from unknown IP addresses"}, {"id": "C", "text": "By replying with ICMP destination unreachable packets"}, {"id": "D", "text": "By dynamically increasing RAM allocation on the host"}]'::jsonb, 'A', 'Hard', 200, 60, 'SYN floods exhaust kernel memory buffers (backlog queue). With SYN cookies, the server stores NO state. When the legitimate client sends the final ACK (with seq+1), the server verifies the cryptographic hash in the ACK number and instantiates the socket only then.', ARRAY['SYN Flood', 'SYN Cookies', 'DDoS Mitigation', 'TCP Security']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0030-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'In Variable Length Subnet Masking (VLSM), how do you partition 192.168.10.0/24 to support Subnet A (100 hosts), Subnet B (50 hosts), and Subnet C (20 hosts) with minimal waste?', NULL, '[{"id": "A", "text": "Subnet A: /25 (128 addresses), Subnet B: /26 (64 addresses), Subnet C: /27 (32 addresses)"}, {"id": "B", "text": "Subnet A: /24, Subnet B: /24, Subnet C: /24"}, {"id": "C", "text": "Subnet A: /28, Subnet B: /28, Subnet C: /28"}, {"id": "D", "text": "Subnet A: /26, Subnet B: /26, Subnet C: /26"}]'::jsonb, 'A', 'Hard', 200, 60, '100 hosts requires 2^7 = 128 block (/25, usable 126 hosts: .0 - .127). 50 hosts requires 2^6 = 64 block (/26, usable 62 hosts: .128 - .191). 20 hosts requires 2^5 = 32 block (/27, usable 30 hosts: .192 - .223). This cleanly fits in /24 without overlap.', ARRAY['VLSM', 'CIDR', 'Subnetting', 'IP Engineering']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0031-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'In BGP path-vector routing, how are routing loops systematically prevented between Autonomous Systems?', NULL, '[{"id": "A", "text": "Every BGP router prepends its own Autonomous System Number (ASN) to the AS_PATH attribute; if a router receives an update containing its OWN ASN in the path, it discards the route"}, {"id": "B", "text": "BGP routers perform ping tests every 10 milliseconds"}, {"id": "C", "text": "BGP routers enforce a maximum hop limit of 15 hops like RIP"}, {"id": "D", "text": "By calculating spanning trees using the 802.1D protocol"}]'::jsonb, 'A', 'Hard', 200, 60, 'AS_PATH lists every ASN through which the prefix advertisement has traveled. When a BGP border speaker inspects incoming routes, seeing its own ASN in the AS_PATH proves the update has looped back, prompting immediate silent rejection.', ARRAY['BGP', 'AS_PATH', 'Loop Prevention', 'Inter-Domain Routing']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0032-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'Why does Diffie-Hellman Ephemeral (DHE / ECDHE) key exchange provide Perfect Forward Secrecy (PFS) where RSA static key exchange fails?', NULL, '[{"id": "A", "text": "DHE generates unique ephemeral key pairs per session; compromising the server''s long-term private key later cannot decrypt previously recorded network traffic because ephemeral keys were destroyed after the session"}, {"id": "B", "text": "DHE uses symmetric encryption keys exclusively"}, {"id": "C", "text": "RSA static exchange does not use certificates"}, {"id": "D", "text": "DHE keys are stored permanently in browser cookies"}]'::jsonb, 'A', 'Hard', 200, 60, 'In RSA key exchange, the client encrypts the premaster secret with the server''s public key. If an adversary records ciphertext and steals the server private key years later, they can decrypt all historical sessions. With Ephemeral DH, keys are discarded after session generation.', ARRAY['Perfect Forward Secrecy', 'ECDHE', 'Cryptography', 'TLS']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0033-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'How does Cyclic Redundancy Check (CRC-32) detect burst errors in Ethernet Data Link frames?', NULL, '[{"id": "A", "text": "By appending a 32-bit checksum representing the remainder of binary polynomial division (modulo-2 arithmetic in Galois Field GF(2)) of the data bits by a standard generator polynomial (e.g. 0x04C11DB7)"}, {"id": "B", "text": "By adding all byte values together in base 10"}, {"id": "C", "text": "By checking parity bits on each individual ASCII character"}, {"id": "D", "text": "By counting the total number of zeros in the frame"}]'::jsonb, 'A', 'Hard', 200, 60, 'CRC treats bit streams as coefficients of polynomials over GF(2). Dividing data by a generator polynomial produces a remainder (FCS). The receiver recalculates division: any bit errors of length <= generator degree (32 bits) or odd bit errors are mathematically detected.', ARRAY['CRC-32', 'Polynomial Arithmetic', 'Error Detection', 'Data Link']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000004-0034-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000004', 'BOSS BATTLE // THE BGP FLAP DAMPING MONARCH:
