INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0001-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What does Idempotency mean in HTTP method specifications (e.g. GET, PUT, DELETE vs POST)?', NULL, '[{"id": "A", "text": "An idempotent method produces the exact same server side-effect whether executed once or executed multiple times consecutively with identical parameters"}, {"id": "B", "text": "The method executes in zero milliseconds"}, {"id": "C", "text": "The method can only be called from mobile devices"}, {"id": "D", "text": "The method encrypts the response body"}]'::jsonb, 'A', 'Easy', 50, 30, 'RFC 7231 defines idempotency: multiple identical requests have the same intended effect on the server as a single request. GET, HEAD, PUT, and DELETE are idempotent; POST is not (repeating POST can create multiple records).', ARRAY['HTTP', 'REST API', 'Idempotency', 'Web Protocols']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0002-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In the standard CSS Box Model, what is the order of layers moving from the innermost element outward to the exterior boundary?', NULL, '[{"id": "A", "text": "Content -> Padding -> Border -> Margin"}, {"id": "B", "text": "Content -> Margin -> Border -> Padding"}, {"id": "C", "text": "Border -> Margin -> Padding -> Content"}, {"id": "D", "text": "Margin -> Border -> Content -> Padding"}]'::jsonb, 'A', 'Easy', 50, 30, 'The CSS box model encloses HTML elements: Content (text/media) is buffered by Padding (clears area around content), wrapped by Border (visible outline), and separated from adjacent elements by Margin (transparent exterior space).', ARRAY['CSS', 'Box Model', 'Web Design']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0003-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What does the Document Object Model (DOM) represent in web browsers?', NULL, '[{"id": "A", "text": "A tree-structured in-memory object representation of the parsed HTML document, enabling programming languages like JavaScript to dynamically manipulate elements, attributes, and styles"}, {"id": "B", "text": "A database server running in the browser"}, {"id": "C", "text": "A proprietary Adobe graphics format"}, {"id": "D", "text": "A network protocol replacing TCP"}]'::jsonb, 'A', 'Easy', 50, 30, 'When a browser parses HTML, it constructs the DOM tree. Nodes in the tree represent elements (div, p, button) that scripts can access, mutate, and bind event handlers to dynamically.', ARRAY['DOM', 'HTML', 'JavaScript', 'Browsers']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0004-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the security purpose of the browser''s Same-Origin Policy (SOP)?', NULL, '[{"id": "A", "text": "To prevent malicious scripts on one origin (protocol + host + port) from reading sensitive data or DOM contents loaded from a distinct origin without explicit CORS permission"}, {"id": "B", "text": "To stop users from viewing webpage HTML source code"}, {"id": "C", "text": "To enforce single-threaded JavaScript execution"}, {"id": "D", "text": "To prevent multiple browser tabs from opening simultaneously"}]'::jsonb, 'A', 'Easy', 50, 30, 'SOP is the cornerstone of web application security: script running at attacker.com cannot read cookies, fetch private APIs, or inspect DOM frames from bank.com unless bank.com explicitly grants access via Cross-Origin Resource Sharing (CORS) headers.', ARRAY['Same-Origin Policy', 'CORS', 'Web Security', 'Browsers']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0005-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What fundamental architectural difference distinguishes a Docker Container from a traditional Virtual Machine (VM)?', NULL, '[{"id": "A", "text": "Containers share the host operating system kernel and isolate processes using kernel namespaces and cgroups; VMs virtualize full hardware and run a complete guest OS on a hypervisor"}, {"id": "B", "text": "Containers are 100x larger in file size than VMs"}, {"id": "C", "text": "VMs do not require RAM memory"}, {"id": "D", "text": "Containers can only run Python code"}]'::jsonb, 'A', 'Easy', 50, 30, 'VMs simulate physical hardware via Type 1 or Type 2 hypervisors, booting redundant guest OS kernels (gigabytes of storage and minutes of boot time). Containers are lightweight Linux processes isolated via namespaces (pid, net, mnt) sharing the host kernel.', ARRAY['Docker', 'Containers', 'Virtual Machines', 'DevOps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0006-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In modern software engineering, what is Continuous Integration (CI)?', NULL, '[{"id": "A", "text": "The automated practice where developers frequently merge code changes into a shared central repository, triggering automated builds, linters, and unit tests to catch defects early"}, {"id": "B", "text": "Continuous manual deployment of zip files to production servers"}, {"id": "C", "text": "Rewriting legacy software every month"}, {"id": "D", "text": "A database backup tool"}]'::jsonb, 'A', 'Easy', 50, 30, 'CI (e.g. GitHub Actions, GitLab CI) automates compilation, testing, and static analysis on every pull request, preventing integration hell and ensuring that master branches remain permanently shippable.', ARRAY['CI/CD', 'Continuous Integration', 'DevOps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0007-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the key storage difference between Browser Cookies and LocalStorage?', NULL, '[{"id": "A", "text": "Cookies are automatically attached to every matching HTTP request header (max ~4KB); LocalStorage stores up to 5-10MB purely on the client side and is never automatically transmitted over the network"}, {"id": "B", "text": "Cookies can store up to 10GB of video files"}, {"id": "C", "text": "LocalStorage is cleared every time a user refreshes the page"}, {"id": "D", "text": "Cookies are encrypted with RSA by default"}]'::jsonb, 'A', 'Easy', 50, 30, 'Cookies travel with every HTTP request (Cookie header), making them suitable for session tokens with HttpOnly flags. LocalStorage provides a persistent key-value store accessible only via client JavaScript for non-sensitive UI settings.', ARRAY['Cookies', 'LocalStorage', 'Client Storage', 'Web']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0008-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'How does the JavaScript runtime execute asynchronous I/O operations despite being single-threaded?', NULL, '[{"id": "A", "text": "Through the Event Loop and Web APIs/libuv: blocking operations (fetch, setTimeout, file I/O) offload to background threads; their completion callbacks enqueue onto the Callback/Microtask Queue and run on the main thread when the call stack clears"}, {"id": "B", "text": "By executing JavaScript bytecode directly on the graphics card"}, {"id": "C", "text": "By dynamically creating new CPU cores"}, {"id": "D", "text": "JavaScript is not single-threaded; it spawns 64 threads by default"}]'::jsonb, 'A', 'Easy', 50, 30, 'Node.js (via libuv) and browsers delegate asynchronous work to native system threads. Once finished, callbacks are placed in the Macrotask or Microtask (Promises) queue. The Event Loop monitors the main Call Stack and executes queued callbacks once the stack empties.', ARRAY['Event Loop', 'JavaScript', 'Asynchronous', 'libuv']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0009-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the function of CSS Media Queries in responsive web development?', '@media (max-width: 768px) {
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0010-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In Git version control, what does the command git commit do compared to git push?', NULL, '[{"id": "A", "text": "git commit records a snapshot of staged changes into the local repository history; git push uploads local commits to a remote repository (e.g. GitHub)"}, {"id": "B", "text": "git commit sends code directly to customer production servers"}, {"id": "C", "text": "git push deletes old branches"}, {"id": "D", "text": "They perform the exact same action"}]'::jsonb, 'A', 'Easy', 50, 30, 'Git is a distributed version control system. Committing is an entirely local offline action that cryptographically packages staged diffs into an immutable commit object. Pushing synchronizes those commits over the network to a remote forge.', ARRAY['Git', 'Version Control', 'DevOps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0011-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'Which data interchange format is text-based, language-independent, and natively parsed into objects in JavaScript?', '{
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0012-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What does a RESTful API''s Statelessness constraint mandate?', NULL, '[{"id": "A", "text": "Every client request to the server must contain all information necessary to understand and process the request; the server must not store client conversational session context between requests"}, {"id": "B", "text": "Servers cannot use databases"}, {"id": "C", "text": "Clients cannot authenticate using passwords"}, {"id": "D", "text": "Requests can only be executed once per day"}]'::jsonb, 'A', 'Easy', 50, 30, 'Statelessness (Fielding dissertation) ensures high horizontal scalability: any server instance in a cluster can handle any incoming request because state is held by the client (e.g. JWT tokens) rather than tied to server sticky sessions.', ARRAY['REST', 'Statelessness', 'API Design']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0013-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In React, how does the Virtual DOM Reconciliation algorithm optimize DOM updates, and why is the ''key'' prop essential in lists?', '<ul>
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0014-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the difference between Server-Side Rendering (SSR) and Static Site Generation (SSG) in Next.js?', NULL, '[{"id": "A", "text": "SSG generates HTML once at build time and serves it instantly from CDN edges; SSR generates fresh HTML dynamically on the server for every incoming request"}, {"id": "B", "text": "SSR only works without CSS"}, {"id": "C", "text": "SSG requires an active Node.js server running 24/7 for each user"}, {"id": "D", "text": "There is no speed difference between them"}]'::jsonb, 'A', 'Medium', 100, 45, 'SSG produces static HTML at `next build`, achieving ultra-fast TTFB via edge caching. SSR renders on-demand per request, essential when pages display live personalized user data or real-time query params.', ARRAY['Next.js', 'SSR', 'SSG', 'Rendering']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0015-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In JavaScript, what is a Closure and how does it affect memory lifecycle?', 'function createCounter() {
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0016-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What are the three dot-separated components of a JSON Web Token (JWT), and how does the server verify its authenticity?', 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyfQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c', '[{"id": "A", "text": "Header, Payload, and Cryptographic Signature: the server hashes Header + Payload using its private secret key and verifies that the output matches the Signature token"}, {"id": "B", "text": "Username, Password, and Database ID"}, {"id": "C", "text": "HTML, CSS, and JavaScript"}, {"id": "D", "text": "Source IP, Destination IP, and Timestamp"}]'::jsonb, 'A', 'Medium', 100, 45, 'A JWT consists of: Header (algorithm & token type), Payload (claims / user attributes), and Signature. Because the signature is HMACSHA256(base64(Header) + ''.'' + base64(Payload), secret), modifying even one character invalidates verification.', ARRAY['JWT', 'Authentication', 'Security', 'Web Tokens']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0017-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'How do Docker Multi-Stage Builds drastically reduce the size and attack surface of production container images?', 'FROM node:20 AS builder
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0018-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the architectural difference between a Forward Proxy and a Reverse Proxy?', NULL, '[{"id": "A", "text": "A Forward Proxy sits in front of clients, mediating requests outward to the internet (protecting/anonymizing clients); a Reverse Proxy sits in front of servers, intercepting incoming client requests for load balancing, caching, and SSL termination"}, {"id": "B", "text": "Forward proxies are written in C; reverse proxies are written in HTML"}, {"id": "C", "text": "A reverse proxy runs on user laptops exclusively"}, {"id": "D", "text": "Forward proxies only support UDP"}]'::jsonb, 'A', 'Medium', 100, 45, 'Forward proxies act on behalf of clients (e.g. corporate internet filtering). Reverse proxies (Nginx, Envoy, Cloudflare) act on behalf of origin backends, hiding server topology, enforcing TLS, rate limiting, and balancing traffic across clusters.', ARRAY['Reverse Proxy', 'Nginx', 'Architecture', 'DevOps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0019-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'How do WebSockets differ from HTTP/1.1 Short Polling and Long Polling for real-time web applications?', NULL, '[{"id": "A", "text": "WebSockets upgrade the initial HTTP connection into a persistent, bidirectional, full-duplex TCP socket, allowing server and client to push microsecond messages with minimal 2-byte framing overhead"}, {"id": "B", "text": "WebSockets do not require a network connection"}, {"id": "C", "text": "Long polling consumes less bandwidth than WebSockets"}, {"id": "D", "text": "WebSockets can only transmit text, never binary"}]'::jsonb, 'A', 'Medium', 100, 45, 'Polling wastes bandwidth by repeatedly sending HTTP headers every second. WebSockets send an HTTP 101 Switching Protocols header once, keeping the TCP connection open for instantaneous two-way data streaming.', ARRAY['WebSockets', 'Real-Time', 'HTTP', 'Transport']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0020-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the Cache-Aside (Lazy Loading) pattern in distributed caching using Redis?', NULL, '[{"id": "A", "text": "The application checks the cache first; on a cache miss, it fetches data from the primary database, writes the result to the cache with a TTL, and returns it to the client"}, {"id": "B", "text": "The database writes to Redis on every row update automatically"}, {"id": "C", "text": "All data is written to Redis and never saved to disk"}, {"id": "D", "text": "Redis invalidates the entire cache every 10 seconds"}]'::jsonb, 'A', 'Medium', 100, 45, 'In Cache-Aside, the application owns cache management: Read path checks cache -> if miss, queries DB -> populates cache. This ensures only requested data is cached, but requires handling potential stale reads until TTL expires.', ARRAY['Redis', 'Caching', 'Cache-Aside', 'System Design']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0021-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the difference between git merge and git rebase when incorporating changes from main into a feature branch?', NULL, '[{"id": "A", "text": "git merge preserves complete commit history and chronological order by creating a new 3-way merge commit; git rebase rewrites project history by replaying feature commits on top of the tip of main for a linear commit graph"}, {"id": "B", "text": "git rebase deletes the feature branch"}, {"id": "C", "text": "git merge is strictly forbidden on all Git projects"}, {"id": "D", "text": "git rebase uploads commits to GitHub automatically"}]'::jsonb, 'A', 'Medium', 100, 45, 'Merge retains true history and branch provenance with explicit merge commits. Rebase shifts the base of the feature branch to main, generating new SHA-1 hashes for replayed commits and producing a clean, straight linear Git history.', ARRAY['Git', 'Merge vs Rebase', 'DevOps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0022-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In Kubernetes architecture, what is the hierarchy of abstraction between a Pod, a Deployment, and a Service?', NULL, '[{"id": "A", "text": "A Pod is the smallest deployable container execution unit; a Deployment manages declarative scaling and rolling updates of replica Pods; a Service provides a stable IP and load balances traffic to matching Pods"}, {"id": "B", "text": "A Service runs inside a Pod; a Pod runs inside a Deployment"}, {"id": "C", "text": "Deployments are physical servers; Pods are virtual networks"}, {"id": "D", "text": "Kubernetes does not have Services"}]'::jsonb, 'A', 'Medium', 100, 45, 'Pods are ephemeral instances with dynamic IPs. Deployments maintain desired replica sets and execute zero-downtime rolling upgrades. Services use label selectors to expose a stable virtual cluster IP and load-balance incoming network traffic.', ARRAY['Kubernetes', 'DevOps', 'Pods', 'Deployments', 'Services']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0023-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'How do Server-Sent Events (SSE) compare to WebSockets for live AI token streaming (such as our CR Socratic Tutor)?', 'HTTP/1.1 200 OK
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0024-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the function of the Content Security Policy (CSP) HTTP header in mitigating Cross-Site Scripting (XSS)?', 'Content-Security-Policy: default-src ''self''; script-src ''self'' https://apis.google.com;', '[{"id": "A", "text": "It restricts the authorized domains and resource types (scripts, images, stylesheets) from which the browser is permitted to load and execute content, blocking injected inline scripts"}, {"id": "B", "text": "It prevents users from taking screenshots"}, {"id": "C", "text": "It encrypts CSS stylesheets with AES-128"}, {"id": "D", "text": "It forces users to change passwords every 30 days"}]'::jsonb, 'A', 'Medium', 100, 45, 'Even if an attacker injects `<script src=''evil.com/xss.js''>` into HTML, a strict CSP instructing `script-src ''self''` orders the browser to abort downloading and executing the script, preventing session theft.', ARRAY['CSP', 'XSS', 'Web Security', 'HTTP Headers']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0025-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'How does setting the SameSite=Strict or SameSite=Lax attribute on session cookies mitigate Cross-Site Request Forgery (CSRF)?', 'Set-Cookie: session_id=xyz; Secure; HttpOnly; SameSite=Lax', '[{"id": "A", "text": "It tells the browser not to attach the cookie to cross-site requests initiated from third-party websites, preventing malicious sites from executing state-changing transactions on behalf of logged-in victims"}, {"id": "B", "text": "It encrypts the database password on the client"}, {"id": "C", "text": "It makes cookies expire after 5 seconds"}, {"id": "D", "text": "It converts HTTP to HTTPS automatically"}]'::jsonb, 'A', 'Medium', 100, 45, 'In a CSRF attack, a trap link on evil.com triggers a POST to bank.com. In the past, browsers sent bank.com cookies automatically. SameSite=Strict/Lax restricts cookie transmission to first-party contexts, neutralizing CSRF attacks at the browser level.', ARRAY['CSRF', 'SameSite', 'Cookies', 'Web Security']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0026-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In a Content Delivery Network (CDN), what does the Cache-Control header directive ''stale-while-revalidate'' instruct?', 'Cache-Control: public, max-age=3600, stale-while-revalidate=86400', '[{"id": "A", "text": "The client/CDN serves stale cached content immediately while asynchronously sending a background revalidation request to the origin server to fetch fresh content for future requests"}, {"id": "B", "text": "The content must never be cached"}, {"id": "C", "text": "The browser deletes cached images immediately"}, {"id": "D", "text": "The web server restarts if a cache miss occurs"}]'::jsonb, 'A', 'Medium', 100, 45, '`stale-while-revalidate` delivers near-zero latency by serving cached assets instantly, while decoupling network revalidation from the user''s critical rendering path by updating the cache in the background.', ARRAY['CDN', 'Cache-Control', 'HTTP Caching', 'Performance']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0027-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In Next.js 14+ and React 19 Server Components (RSC), how does the RSC Streaming Wire Format differ from traditional client-side hydration payloads?', NULL, '[{"id": "A", "text": "RSC streams serialized JSON-like component descriptions and UI slots containing suspended component boundaries, rendering static HTML directly from the server while reducing client JavaScript bundle size by eliminating server component code from client bundles"}, {"id": "B", "text": "RSC replaces HTML with WebAssembly binaries"}, {"id": "C", "text": "RSC requires all state to be stored in Redux"}, {"id": "D", "text": "RSC does not support CSS stylesheets"}]'::jsonb, 'A', 'Hard', 200, 60, 'Traditional SSR ships both HTML and all the JavaScript required to re-execute every component on the client. React Server Components execute strictly on the server: their JS dependencies (Markdown parsers, database clients) are never downloaded by the browser.', ARRAY['React 19', 'RSC', 'Server Components', 'Next.js Architecture']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0028-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'What is the difference between Blue-Green Deployment and Canary Deployment strategies in cloud DevOps?', NULL, '[{"id": "A", "text": "Blue-Green deploys an identical second environment and cuts 100% of traffic over at the router/load balancer; Canary routes a small percentage (e.g. 5%) of live production traffic to the new version to monitor metrics before gradual rollout"}, {"id": "B", "text": "Blue-Green takes 48 hours to complete; Canary takes 1 second"}, {"id": "C", "text": "Canary deployment only works on Kubernetes in cloud environments"}, {"id": "D", "text": "Blue-Green requires rewriting the database schema from scratch"}]'::jsonb, 'A', 'Hard', 200, 60, 'Blue-Green provides instant atomic rollback by flipping router endpoints between two identical production environments. Canary minimizes blast radius by testing new versions on real users with automated metric guardrails before full deployment.', ARRAY['Deployments', 'Blue-Green', 'Canary', 'DevOps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0029-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'How does Database Connection Pooling prevent connection starvation and high latency in asynchronous server environments (e.g. Node.js with Prisma)?', NULL, '[{"id": "A", "text": "It maintains a pre-warmed pool of reusable, persistent TCP/TLS database socket connections, queuing incoming queries to avoid the expensive overhead of establishing a new database handshake and process per query"}, {"id": "B", "text": "It executes queries on client browsers"}, {"id": "C", "text": "It bypasses database authentication credentials"}, {"id": "D", "text": "It converts relational databases into static JSON files"}]'::jsonb, 'A', 'Hard', 200, 60, 'Establishing a database connection requires TCP 3-way handshake, TLS negotiation, authentication, and backend process spawning (PostgreSQL forks a backend per connection). Connection pools (e.g. PgBouncer, Prisma Pool) multiplex thousands of queries over a fixed pool.', ARRAY['Connection Pooling', 'Prisma', 'Databases', 'Performance']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0030-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In distributed systems observability, what role do Trace ID and Span ID play according to OpenTelemetry standards?', 'traceparent: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01', '[{"id": "A", "text": "Trace ID represents the end-to-end journey of a single client transaction across multiple microservices; Span ID represents a specific timed unit of work or sub-operation within that distributed trace"}, {"id": "B", "text": "Trace ID stores the user''s password hash; Span ID stores the database port"}, {"id": "C", "text": "They are used exclusively for billing cloud costs"}, {"id": "D", "text": "Trace ID measures network ping latency"}]'::jsonb, 'A', 'Hard', 200, 60, 'Distributed tracing propagates context via W3C Trace Context headers (traceparent). The Trace ID correlates logs, metrics, and network calls across dozens of decoupled microservices, while parent-child Span IDs measure individual service execution intervals.', ARRAY['OpenTelemetry', 'Distributed Tracing', 'Observability', 'Microservices']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0031-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In Kubernetes, how does the Horizontal Pod Autoscaler (HPA) algorithm calculate the desired number of replicas?', 'desiredReplicas = ceil( currentReplicas * ( currentMetricValue / targetMetricValue ) )', '[{"id": "A", "text": "By calculating the ratio of currently observed metric utilization (e.g. CPU or custom Prometheus metrics) against target utilization, scaling replica counts proportionally"}, {"id": "B", "text": "By doubling pods every 5 minutes regardless of load"}, {"id": "C", "text": "By shutting down nodes during peak traffic"}, {"id": "D", "text": "By checking the master node temperature"}]'::jsonb, 'A', 'Hard', 200, 60, 'HPA queries the Metrics Server in a control loop (every 15s). If current CPU utilization is 80% and target is 50%, desiredReplicas = ceil(current * (80/50)), smoothly adding pods to maintain stability without thrashing.', ARRAY['Kubernetes', 'HPA', 'Autoscaling', 'DevOps']::text[]);
INSERT INTO questions (id, subject_id, question_text, code_snippet, options, correct_option_id, difficulty, xp_reward, time_limit_seconds, explanation, tags) VALUES ('b0000006-0032-0000-0000-000000000000', 'a0000001-0000-0000-0000-000000000006', 'In Infrastructure as Code (IaC) with Terraform, why is State Locking with remote backends (e.g. AWS S3 + DynamoDB) critical in team environments?', NULL, '[{"id": "A", "text": "To prevent concurrent terraform apply executions from mutating the state file simultaneously, preventing state corruption, race conditions, and duplicate cloud resource provisioning"}, {"id": "B", "text": "To prevent unauthorized users from viewing AWS bills"}, {"id": "C", "text": "To speed up Terraform compilation time"}, {"id": "D", "text": "To compress terraform files into zip archives"}]'::jsonb, 'A', 'Hard', 200, 60, 'The terraform.tfstate file maps declarative code to real-world cloud resources. If two CI/CD pipelines run simultaneously without distributed locking (via DynamoDB or Consul), writes interleave, corrupting state and causing resource leaks.', ARRAY['Terraform', 'IaC', 'State Locking', 'DevOps']::text[]);
