FROM node:20-alpine AS runner
WORKDIR /app
COPY --from=builder /app/.next/standalone ./
CMD ["node", "server.js"]', '[{"id": "A", "text": "By executing compilation in heavy build environments, and copying ONLY compiled production artifacts into a clean, minimal runtime base image, leaving compilers, devDependencies, and source code behind"}, {"id": "B", "text": "By compressing images with gzip"}, {"id": "C", "text": "By disabling root access inside the container"}, {"id": "D", "text": "By running multiple containers on a single port"}]'::jsonb, 'A', 'Medium', 100, 45, 'Build tools (TypeScript, build-essential, npm caches) can balloon an image to 1.5GB. Multi-stage builds compile in stage 1, then copy only standalone build outputs into an Alpine Linux container, shrinking images to under 100MB and eliminating compiler vulnerabilities.', ARRAY['Docker', 'Multi-Stage', 'DevOps', 'Container Security']::text[]);
